import { test, expect } from '@playwright/test';
import path from 'path';
import fs from 'fs';
import os from 'os';

test.describe('Multiple File Upload', () => {
  let tempDir: string;
  let testFiles: string[] = [];

  test.beforeEach(async ({ page }) => {
