    await page.goto('data:text/html,<html><body><input type="file" id="fileInput" multiple accept=".txt,.pdf" /><button id="uploadBtn">Upload Files</button><div id="uploadStatus"></div><ul id="fileList"></ul></body></html>');
  });

  test('should upload multiple files successfully', async ({ page }) => {
